mapper.select:
SELECT T1.FINPROD_ID, T1.FINPROD_NAME, T1.FINPROD_ABBR, T1.TRUSTEE_ID, T1.ISSUER, T1.MANAGER, T1.FINANCIER, T5.LIST_ID, T5.LIST_TYPE, T5.LIST_NAME, T4.LIST_DETAIL_ID_TYPE FROM FIN_PRODUCT T1 INNER JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE_CONFIG T3 ON (nvl(T3.INPUT_VALUE_1,'null') = 'null' or T2.TYPE_8 = T3.INPUT_VALUE_1) AND (nvl(T3.INPUT_VALUE_2,'null') = 'null' or T2.TYPE_9 = T3.INPUT_VALUE_2) AND (nvl(T3.INPUT_VALUE_3,'null') = 'null' or T2.TYPE_10 = T3.INPUT_VALUE_3) AND (nvl(T3.INPUT_VALUE_4,'null') = 'null' or T2.TYPE_11 = T3.INPUT_VALUE_4) AND (nvl(T3.INPUT_VALUE_5,'null') = 'null' or T2.TYPE_12 = T3.INPUT_VALUE_5)
AND T3.CONFIG_TYPE = #{RISK_TYPE}
LEFT JOIN RSK_ACCESS_LIST_TYPE T4 ON T4.RSK_ASSET_TYPE1 = T3.OUTPUT_VALUE_1 AND (nvl(T3.OUTPUT_VALUE_2,'null') = 'null' or T4.RSK_ASSET_TYPE2 = T3.OUTPUT_VALUE_2) AND (nvl(T3.OUTPUT_VALUE_3,'null') = 'null' or T4.RSK_ASSET_TYPE3 = T3.OUTPUT_VALUE_3) AND (nvl(T3.OUTPUT_VALUE_4,'null') = 'null' or T4.RSK_ASSET_TYPE4 = T3.OUTPUT_VALUE_4) AND (nvl(T3.OUTPUT_VALUE_5,'null') = 'null' or T4.RSK_ASSET_TYPE5 = T3.OUTPUT_VALUE_5) LEFT JOIN RSK_ACCESS_LIST T5 ON T5.LIST_ID = T4.LIST_ID
AND T5.DELDATE > #{listDate}
T1.FINPROD_ID = #{finprodId}

SELECT T5.LIST_ID, T5.LIST_TYPE, T5.LIST_NAME, T4.LIST_DETAIL_ID_TYPE FROM FIN_PRODUCT_TYPE_CONFIG T3 LEFT JOIN RSK_ACCESS_LIST_TYPE T4 ON T4.RSK_ASSET_TYPE1 = T3.OUTPUT_VALUE_1 AND ( nvl( T3.OUTPUT_VALUE_2, 'null' ) = 'null' OR T4.RSK_ASSET_TYPE2 = T3.OUTPUT_VALUE_2 ) AND ( nvl( T3.OUTPUT_VALUE_3, 'null' ) = 'null' OR T4.RSK_ASSET_TYPE3 = T3.OUTPUT_VALUE_3 ) AND ( nvl( T3.OUTPUT_VALUE_4, 'null' ) = 'null' OR T4.RSK_ASSET_TYPE4 = T3.OUTPUT_VALUE_4 ) AND ( nvl( T3.OUTPUT_VALUE_5, 'null' ) = 'null' OR T4.RSK_ASSET_TYPE5 = T3.OUTPUT_VALUE_5 ) LEFT JOIN RSK_ACCESS_LIST T5 ON T5. LIST_ID = T4.LIST_ID
AND T5.DELDATE > #{listDate}
T3.CONFIG_TYPE = 'NO_TARGET_TYPE_MAPPING'
AND T3.INPUT_VALUE_1 = #{inputValue1}
AND T3.INPUT_VALUE_2 = #{inputValue2}
AND T3.INPUT_VALUE_3 = #{inputValue3}

SELECT T1.FINPROD_ID, T1.FINPROD_NAME, T1.FINPROD_ABBR, T1.TRUSTEE_ID, T1.ISSUER, T1.MANAGER, T1.FINANCIER, T5.LIST_ID, T4.LIST_DETAIL_ID_TYPE, T5.LIST_TYPE, T5.LIST_DETAIL_TYPE FROM FIN_PRODUCT T1 INNER JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE_CONFIG T3 ON T3.INPUT_VALUE_1 = T2.TYPE_8 AND T3.INPUT_VALUE_2 = T2.TYPE_9 AND T3.INPUT_VALUE_3 = T2.TYPE_10 AND T3.INPUT_VALUE_4 = T2.TYPE_11 AND T3.INPUT_VALUE_5 = T2.TYPE_12 AND T3.CONFIG_TYPE = 'RISK_TYPE' LEFT JOIN RSK_ACCESS_LIST_TYPE T4 ON T4.RSK_ASSET_TYPE1 = T3.OUTPUT_VALUE_1 AND (nvl(T3.OUTPUT_VALUE_2,'null') = 'null' or T4.RSK_ASSET_TYPE2 = T3.OUTPUT_VALUE_2) AND (nvl(T3.OUTPUT_VALUE_3,'null') = 'null' or T4.RSK_ASSET_TYPE3 = T3.OUTPUT_VALUE_3) AND (nvl(T3.OUTPUT_VALUE_4,'null') = 'null' or T4.RSK_ASSET_TYPE4 = T3.OUTPUT_VALUE_4) AND (nvl(T3.OUTPUT_VALUE_5,'null') = 'null' or T4.RSK_ASSET_TYPE5 = T3.OUTPUT_VALUE_5) LEFT JOIN RSK_ACCESS_LIST T5 ON T5.LIST_ID = T4.LIST_ID
AND T5.DELDATE > #{listDate}
T1.FINPROD_MARKET_ID = #{finprodId}

        SELECT
	        INSTITUTION_CODE insitituteCode /* edit by songyawei 20200701 */
	    FROM (
	        SELECT RSK_ACCESS_LIST_DETAIL.LIST_ID,RSK_ACCESS_LIST_DETAIL.INSTITUTION_CODE /* add by songyawei 20200701 */ FROM
	        RSK_ACCESS_LIST_DETAIL where LIST_ID = #{listId}

                AND LIST_DETAIL_ID = #{finprodId,jdbcType=VARCHAR}

	        UNION ALL
	        SELECT RSK_ACCESS_LIST_DETAIL.LIST_ID,RSK_ACCESS_LIST_DETAIL.INSTITUTION_CODE /* add by songyawei 20200701 */ FROM
	        RSK_ACCESS_LIST_DETAIL 
	        LEFT JOIN FIN_PRODUCT
	               ON RSK_ACCESS_LIST_DETAIL.LIST_DETAIL_ID = FIN_PRODUCT.FINPROD_MARKET_ID
	        where LIST_ID = #{listId}

                AND FIN_PRODUCT.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

	     )
